def extract_stems(pairs):
    stems = []
    visited = set()
    # find stems (consecutive pairs)
    for (a,b) in sorted(pairs.items()):
        if a < b and a not in visited:
            stem = [(a,b)]
            visited.add(a); visited.add(b)
            # extend
            for k in range(1, 100):
                na, nb = a+k, b-k
                if na in pairs and pairs[na] == nb and na < nb:
                    stem.append((na,nb))
                    visited.add(na); visited.add(nb)
                else:
                    break
            stems.append(stem)
    return stems

